    'Flytt hele den lagrede samtalen, sjekklisten, vedleggene og filene. Leveringsøkter og legitimasjon blir værende her. Tråden på målet bruker standardkjøringsmiljøet på den datamaskinen, med ikke mer tilgang enn denne tråden har. Ingenting kjøres før du sender neste melding der. Du kan endre modellen etter at den åpnes. Denne tråden blir værende her, skrivebeskyttet, for gjenoppretting.',
