    'Slå på datamaskinbruk for agenter på denne datamaskinen',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Gir agenter med skriveadgang tilgang til skrivebordet på denne datamaskinen. Agenter med skrivebeskyttet tilgang er utelatt. Brukeren og agentene deler skrivebordet og apptilstanden.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'La Cua Driver-feltet stå tomt for å finne det på PATH-en til denne datamaskinen eller i standardinstallasjonsmappen. Endringer gjelder nye agentturer.',
  '1. Install on this computer': '1. Installer på denne datamaskinen',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Kjør det offisielle installasjonsprogrammet på kjøremiljøverten, og oppdater deretter statusen. Det laster ned og installerer CuaDriver; du trenger ikke en Cua-konto.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Minimale Linux-systemer trenger libxi6 og at-spi2-core. GNOME trenger den medfølgende WinRects-hjelperen fra Cua; se installasjonsveiledningen.',
  'Install and set up Cua Driver': 'Installer og konfigurer Cua Driver',
  'Detect / check Cua Driver': 'Finn / kontroller Cua Driver',
  '2. Permissions & desktop access': '2. Tillatelser og skrivebordstilgang',
  '3. Agent MCP, skills & hooks': '3. Agent-MCP, ferdigheter og hooks',
  '4. Computer History (optional preview)': '4. Computer History (valgfri forhåndsvisning)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Gi CuaDriver tilgang til Tilgjengelighet og Skjermopptak i macOS, og godta at programmet startes på nytt. Test av skrivebordstilgang viser apper uten å endre dem. Deamonkontroller påvirker aktive økter for datamaskinbruk.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Lagre bryteren for datamaskinbruk for å aktivere automatisk dovo_cua MCP på nye skrivetilganger. Manuell MCP-registrering er ikke nødvendig. Installer den valgfrie offisielle ferdighetspakken; installasjonen kobler til agenter som er funnet på denne datamaskinen.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Valgfri, kryptert historikk med bare metadata. Aktivering kan starte daemonen på nytt. Deaktivering beholder registrerte data; pause stopper registreringen midlertidig. Bygg som ikke støttes, rapporterer en feil. Dataene lagres på kjøremiljøverten; Vis nylig historikk henter opptil 20 hendelser hit.',
  'Delete recorded Computer History?': 'Slette registrert Computer History?',
