  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Kjører agenten for hver ny samtale, kommandoene og terminalene dens i en lokal Docker- eller Podman-container. Bare arbeidskopien og innloggingen til den valgte agenten monteres. Pågående samtaler beholder innstillingen sin.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Uten nettverkstilgang når ikke agenten modell-API-et sitt, med mindre det API-et kjører i sandkassen. Pakkeinstallasjoner og nettforespørsler mislykkes også.',
