    'Agenten kjører på denne datamaskinen med brukerkontoen din.',
  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    'Agenten, kommandoene og terminalene dens kjører i en container. Bare denne arbeidskopien og innloggingen til agenten monteres.',
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Holder tilbake nytt arbeid som kjører uten melding fra deg, når den anslåtte kostnaden når grensen. Dette gjelder oppfølginger fra Boter, rutinetrinn i en Bot, planlagte meldinger og underagenter. Hver tråd eller Bot telles sammen med sine underagenter. En rutine uten Bot starter en ny telling ved hver kjøring. Angi dens egne grenser under Overvåking og grenser. Din neste melding eller Fortsett nullstiller tellingen. Turer uten pris holder også tilbake arbeid. En pågående tur fullføres alltid.',
